using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace ClearDisk {
 internal sealed class AdvancedAdministrationForm:Form {
  readonly AdvancedAdministrationEngine engine;readonly ComboBox category=new ComboBox(),target=new ComboBox();readonly NumericUpDown initial=new NumericUpDown(),maximum=new NumericUpDown();readonly CheckBox removeC=new CheckBox();
  readonly Button read=new Button(),preview=new Button(),execute=new Button(),create=new Button(),cancel=new Button(),elevate=new Button(),restore=new Button(),nativeSettings=new Button();readonly ListView records=new ListView();readonly TextBox detail=new TextBox();readonly Label status=new Label();AdministrationPlan plan;bool busy,mutation;CancellationTokenSource cancellation;
  static readonly AdministrationKind[] Kinds={AdministrationKind.Drivers,AdministrationKind.RestorePoints,AdministrationKind.Pagefile,AdministrationKind.Software,AdministrationKind.Packages};
  internal AdvancedAdministrationForm():this(new AdvancedAdministrationEngine(),AdministrationKind.Drivers){}
  internal AdvancedAdministrationForm(AdvancedAdministrationEngine service,AdministrationKind selected){
   engine=service;Text="系统与软件管理 · 逐项预览确认";Name="AdvancedAdministrationForm";Font=new Font("Microsoft YaHei UI",9);Size=new Size(1240,850);MinimumSize=new Size(1050,720);StartPosition=FormStartPosition.CenterParent;
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),RowCount=6,ColumnCount=1};foreach(int height in new[]{72,45,75})layout.RowStyles.Add(new RowStyle(SizeType.Absolute,height));layout.RowStyles.Add(new RowStyle(SizeType.Percent,55));layout.RowStyles.Add(new RowStyle(SizeType.Percent,45));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,48));Controls.Add(layout);
   layout.Controls.Add(new Label{Dock=DockStyle.Fill,Text="驱动包、还原点、分页文件和软件操作均需单独预览及管理员确认，不会随扫描自动执行。\r\n应用搬家使用 Windows 支持的 MSIX/Appx 移动；普通安装软件请使用厂商迁移方式或卸载后重装。便携目录迁移仍在原入口。\r\n驱动/还原点删除及软件卸载无法由本工具撤销；分页配置需重启生效，不自动重启。"},0,0);
   var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,AutoScroll=true};category.DropDownStyle=ComboBoxStyle.DropDownList;category.Width=185;category.Items.AddRange(new object[]{"第三方驱动包","系统还原点","分页文件配置","登记软件卸载","Windows应用搬家"});actions.Controls.Add(category);
   var buttons=new[]{read,preview,execute,create,restore,nativeSettings,cancel,elevate};var names=new[]{"读取库存","预览所选动作","确认执行…","创建还原点预览","配置备份 / 恢复…","Windows原生设置…","取消查询","管理员管理窗口"};for(int i=0;i<buttons.Length;i++){buttons[i].Text=names[i];buttons[i].AutoSize=true;actions.Controls.Add(buttons[i]);}layout.Controls.Add(actions,0,1);
   var settings=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true};target.DropDownStyle=ComboBoxStyle.DropDownList;target.Width=270;target.AccessibleName="目标固定卷或应用卷";settings.Controls.Add(new Label{AutoSize=true,Text="目标：",Padding=new Padding(0,8,0,0)});settings.Controls.Add(target);
   initial.Minimum=16;initial.Maximum=1048576;initial.Value=1024;maximum.Minimum=16;maximum.Maximum=1048576;maximum.Value=4096;foreach(var label in new[]{"初始 MB","最大 MB"}){settings.Controls.Add(new Label{Text=label,AutoSize=true,Padding=new Padding(0,8,0,0)});settings.Controls.Add(label=="初始 MB"?initial:maximum);}removeC.Text="迁走 C 盘分页配置（转储需要时会拒绝）";removeC.AutoSize=true;settings.Controls.Add(removeC);layout.Controls.Add(settings,0,2);
   records.Dock=DockStyle.Fill;records.View=View.Details;records.FullRowSelect=true;records.MultiSelect=false;records.HideSelection=false;records.Columns.Add("名称",320);records.Columns.Add("身份",300);records.Columns.Add("资格 / 原因",520);layout.Controls.Add(records,0,3);
   detail.Dock=DockStyle.Fill;detail.Multiline=true;detail.ReadOnly=true;detail.ScrollBars=ScrollBars.Both;detail.WordWrap=false;detail.MaxLength=0;layout.Controls.Add(detail,0,4);status.Dock=DockStyle.Fill;status.Text="尚未查询。没有准备任何操作。";layout.Controls.Add(status,0,5);
   category.SelectedIndex=Array.IndexOf(Kinds,selected)<0?0:Array.IndexOf(Kinds,selected);category.SelectedIndexChanged+=delegate{records.Items.Clear();target.Items.Clear();InvalidatePlan();UpdateFields();};read.Click+=async delegate{await Read();};cancel.Click+=delegate{if(cancellation!=null&&!mutation)cancellation.Cancel();};preview.Click+=async delegate{await Prepare(false);};create.Click+=async delegate{await Prepare(true);};restore.Click+=async delegate{await RestoreConfiguration();};nativeSettings.Click+=delegate{try{if(SelectedKind==AdministrationKind.Pagefile)Process.Start(new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"SystemPropertiesAdvanced.exe")){UseShellExecute=true});else Process.Start(new ProcessStartInfo("ms-settings:appsfeatures"){UseShellExecute=true});}catch(Exception e){detail.Text=e.Message;}};execute.Click+=async delegate{await Execute();};
   records.SelectedIndexChanged+=delegate{InvalidatePlan();if(records.SelectedItems.Count==1){var row=(AdministrationRecord)records.SelectedItems[0].Tag;detail.Text=row.Name+"\r\n"+row.Reason+"\r\n"+String.Join("\r\n",row.Fields.Select(f=>f.Key+": "+f.Value));}};target.SelectedIndexChanged+=delegate{InvalidatePlan();};initial.ValueChanged+=delegate{InvalidatePlan();};maximum.ValueChanged+=delegate{InvalidatePlan();};removeC.CheckedChanged+=delegate{InvalidatePlan();};
   elevate.Click+=delegate{try{Process.Start(new ProcessStartInfo(System.Reflection.Assembly.GetExecutingAssembly().Location,"--advanced-administration-window"){UseShellExecute=true,Verb="runas"});}catch(System.ComponentModel.Win32Exception e){if(e.NativeErrorCode!=1223)MessageBox.Show(this,e.Message,Text);}};
   FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy){e.Cancel=true;if(!mutation)cancellation.Cancel();status.Text=mutation?"等待当前系统操作结束后再关闭。":"正在取消查询。";}};UpdateFields();SetBusy(false,false);
  }
  AdministrationKind SelectedKind{get{return Kinds[category.SelectedIndex];}}
  void InvalidatePlan(){plan=null;execute.Enabled=false;}
  void UpdateFields(){bool page=SelectedKind==AdministrationKind.Pagefile,packages=SelectedKind==AdministrationKind.Packages;target.Enabled=page||packages;initial.Enabled=maximum.Enabled=removeC.Enabled=page;create.Visible=SelectedKind==AdministrationKind.RestorePoints;restore.Visible=page;nativeSettings.Visible=page||packages||SelectedKind==AdministrationKind.Software;}
  void SetBusy(bool value,bool changing){busy=value;mutation=changing;category.Enabled=read.Enabled=preview.Enabled=elevate.Enabled=nativeSettings.Enabled=!value;records.Enabled=!value;execute.Enabled=!value&&plan!=null;create.Enabled=restore.Enabled=!value;cancel.Enabled=value&&!changing;if(value){target.Enabled=initial.Enabled=maximum.Enabled=removeC.Enabled=false;}else UpdateFields();}
  sealed class Target{internal string Id,Label;public override string ToString(){return Label;}}
  async Task RestoreConfiguration(){if(busy||engine.Configurations==null)return;try{string[] ids=engine.Configurations.List();using(var dialog=new Form{Text="选择变更前分页配置备份",Size=new Size(650,450),StartPosition=FormStartPosition.CenterParent}){var list=new ListBox{Dock=DockStyle.Fill};list.Items.AddRange(ids);var select=new Button{Text="预览恢复所选配置",Dock=DockStyle.Bottom,Height=40,DialogResult=DialogResult.OK};dialog.Controls.Add(list);dialog.Controls.Add(select);dialog.AcceptButton=select;if(dialog.ShowDialog(this)!=DialogResult.OK||list.SelectedItem==null)return;string id=(string)list.SelectedItem;SetBusy(true,false);cancellation=new CancellationTokenSource();try{plan=await Task.Run(()=>engine.Preview(AdministrationAction.RestorePagefile,"pagefile-config",new Dictionary<string,string>{{"BackupId",id}},cancellation.Token));detail.Text=plan.Description+"\r\n"+plan.Parameters["RestoreSettings"];status.Text="已准备配置恢复预览；确认执行后才更改，重启生效。";}finally{cancellation.Dispose();cancellation=null;SetBusy(false,false);}}}catch(Exception e){detail.Text=e.Message;InvalidatePlan();}}
  async Task Read(){if(busy)return;InvalidatePlan();records.Items.Clear();target.Items.Clear();SetBusy(true,false);cancellation=new CancellationTokenSource();status.Text="正在读取系统登记；不会更改配置。";try{var kind=SelectedKind;var values=await Task.Run(()=>engine.Read(kind,cancellation.Token));foreach(var row in values)records.Items.Add(new ListViewItem(new[]{row.Name,row.Id,(row.Eligible?"可预览：":"不可执行：")+row.Reason}){Tag=row});
   if(kind==AdministrationKind.Pagefile)foreach(var drive in DriveInfo.GetDrives().Where(d=>d.DriveType==DriveType.Fixed&&d.Name[0]!='C'))target.Items.Add(new Target{Id=drive.Name,Label=drive.Name});
   if(kind==AdministrationKind.Packages){var volumes=await Task.Run(()=>engine.Read(AdministrationKind.PackageVolumes,cancellation.Token));foreach(var volume in volumes.Where(v=>v.Eligible))target.Items.Add(new Target{Id=volume.Id,Label=volume.Name});}
   status.Text="读取 "+values.Length+" 项；未自动选择。选择一项查看详情并预览。";
  }catch(OperationCanceledException){status.Text="查询已取消，结果不完整。";}catch(Exception e){detail.Text=e.Message;status.Text="查询失败；可能需要管理员权限或系统不支持，不能视为没有项目。";}finally{cancellation.Dispose();cancellation=null;SetBusy(false,false);}}
  async Task Prepare(bool creating){if(busy)return;InvalidatePlan();if(!creating&&records.SelectedItems.Count!=1){status.Text="请先读取库存并选择一项。";return;}var kind=SelectedKind;var action=creating?AdministrationAction.CreateRestorePoint:kind==AdministrationKind.Drivers?AdministrationAction.DeleteDriver:kind==AdministrationKind.RestorePoints?AdministrationAction.DeleteRestorePoint:kind==AdministrationKind.Pagefile?AdministrationAction.ConfigurePagefile:kind==AdministrationKind.Software?AdministrationAction.UninstallSoftware:AdministrationAction.MovePackage;var args=new Dictionary<string,string>();
   if(kind==AdministrationKind.Pagefile||kind==AdministrationKind.Packages){var selected=target.SelectedItem as Target;if(selected==null){status.Text="请先选择目标卷。";return;}args[kind==AdministrationKind.Pagefile?"Drive":"Volume"]=selected.Id;}
   if(kind==AdministrationKind.Pagefile){args["InitialMB"]=initial.Value.ToString(System.Globalization.CultureInfo.InvariantCulture);args["MaximumMB"]=maximum.Value.ToString(System.Globalization.CultureInfo.InvariantCulture);args["RemoveC"]=removeC.Checked.ToString();}
   string id=creating?"create":((AdministrationRecord)records.SelectedItems[0].Tag).Id;SetBusy(true,false);cancellation=new CancellationTokenSource();try{plan=await Task.Run(()=>engine.Preview(action,id,args,cancellation.Token));detail.Text=plan.Description+"\r\n\r\n原始状态：\r\n"+String.Join("\r\n",plan.Record.Fields.Select(p=>p.Key+": "+p.Value));status.Text="预览有效10分钟；确认后才执行，权限或项目变化需重新预览。";}catch(Exception e){plan=null;detail.Text=e.Message;status.Text="没有准备可执行计划。";}finally{cancellation.Dispose();cancellation=null;SetBusy(false,false);}}
  async Task Execute(){if(busy||plan==null)return;var prepared=plan;if(MessageBox.Show(this,prepared.Description+"\r\n\r\n确认执行这项系统/软件操作？","确认具体操作",MessageBoxButtons.OKCancel,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)!=DialogResult.OK)return;plan=null;SetBusy(true,true);try{var result=await Task.Run(()=>engine.Execute(prepared,true,CancellationToken.None));detail.Text=result.Output+"\r\n"+result.Error;status.Text=result.ExitCode==3010?"配置已提交，需要重启；本程序不会自动重启。":result.Success?"操作完成，请重新读取库存核对。":"操作失败或部分完成，退出码 "+result.ExitCode+"；请检查日志并重新查询。";}catch(Exception e){detail.Text=e.Message;status.Text="操作未确认成功；请检查状态后重新预览。";}finally{SetBusy(false,false);}}
 }
 internal sealed class RuleSettingsForm:Form {
  string capturedDiagnostics;readonly RuleReleaseManager manager;readonly ComboBox versions=new ComboBox();readonly TextBox detail=new TextBox();
  internal RuleSettingsForm(){manager=new RuleReleaseManager(AppDomain.CurrentDomain.BaseDirectory);Text="规则版本 / 回退 / 诊断";Font=new Font("Microsoft YaHei UI",9);Size=new Size(850,620);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),RowCount=3,ColumnCount=1};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,75));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,45));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));Controls.Add(layout);layout.Controls.Add(new Label{Dock=DockStyle.Fill,Text="可启用随包审核的固定规则版本，也可选择旧版本回退。切换后必须关闭已有扫描窗口再重新扫描。\r\n不接受任意下载脚本；新规则版本通过完整验证发行包提供。诊断导出不执行清理，可能包含当前用户标识。"},0,0);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};versions.DropDownStyle=ComboBoxStyle.DropDownList;versions.Items.AddRange(manager.List().Select(v=>(object)v.Version).ToArray());versions.SelectedIndex=0;var activate=new Button{Text="启用所选版本",AutoSize=true};var export=new Button{Text="导出诊断…",AutoSize=true};var checks=new Button{Text="只读环境检查",AutoSize=true};actions.Controls.AddRange(new Control[]{versions,activate,export,checks});checks.Click+=async delegate{checks.Enabled=false;try{capturedDiagnostics=await Task.Run(()=>EnvironmentDiagnostics.Capture(new WindowsAdministrationBackend(),CancellationToken.None,null));detail.Text=capturedDiagnostics;}catch(Exception e){detail.Text=e.Message;}finally{checks.Enabled=true;}};layout.Controls.Add(actions,0,1);detail.Multiline=true;detail.ReadOnly=true;detail.ScrollBars=ScrollBars.Both;detail.Dock=DockStyle.Fill;layout.Controls.Add(detail,0,2);activate.Click+=delegate{try{manager.Activate((string)versions.SelectedItem);capturedDiagnostics=null;detail.Text="已启用 "+versions.SelectedItem+"；旧扫描计划不沿用，请关闭后重新扫描。\r\n"+manager.Diagnostics();}catch(Exception e){detail.Text=e.Message;}};export.Click+=delegate{using(var dialog=new SaveFileDialog{Filter="JSON|*.json",FileName="CDriveCleaner-diagnostics-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".json",OverwritePrompt=false}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{string path=NativeFiles.Normalize(dialog.FileName);EnvironmentDiagnostics.SaveNew(path,capturedDiagnostics??manager.Diagnostics());detail.Text="诊断已保存："+path;}catch(Exception e){detail.Text="未导出："+e.Message;}}};try{detail.Text=manager.Diagnostics();}catch(Exception e){detail.Text=e.Message;}}
 }
